!function(){"use strict";
/* === Scroll / Header === */
function updateScrolled(){var b=document.querySelector("body"),h=document.querySelector("#header");if(h&&(h.classList.contains("scroll-up-sticky")||h.classList.contains("sticky-top")||h.classList.contains("fixed-top"))){window.scrollY>100?b.classList.add("scrolled"):b.classList.remove("scrolled")}}
"www.corporategifts.id"===window.location.hostname&&window.location.replace("https://corporategifts.id"+window.location.pathname+window.location.search+window.location.hash);
document.addEventListener("scroll",updateScrolled,{passive:true});
window.addEventListener("load",updateScrolled);

/* === Mobile Nav === */
var mnt=document.querySelector(".mobile-nav-toggle");
function toggleMobileNav(){document.querySelector("body").classList.toggle("mobile-nav-active");mnt.classList.toggle("bi-list");mnt.classList.toggle("bi-x")}
if(mnt){mnt.addEventListener("click",toggleMobileNav)}
document.querySelectorAll("#navmenu a").forEach(function(a){a.addEventListener("click",function(){document.querySelector(".mobile-nav-active")&&!a.classList.contains("toggle-dropdown")&&toggleMobileNav()})});
document.querySelectorAll(".navmenu .toggle-dropdown").forEach(function(el){el.addEventListener("click",function(e){e.preventDefault();this.parentNode.classList.toggle("active");this.parentNode.nextElementSibling.classList.toggle("dropdown-active");e.stopImmediatePropagation()})});

/* === Scroll Top === */
var st=document.querySelector(".scroll-top");
function updateScrollTop(){if(st){window.scrollY>100?st.classList.add("active"):st.classList.remove("active")}}
if(st){st.addEventListener("click",function(e){e.preventDefault();window.scrollTo({top:0,behavior:"smooth"})})}
window.addEventListener("load",updateScrollTop);
document.addEventListener("scroll",updateScrollTop,{passive:true});

/* === AOS: via requestIdleCallback after load === */
function initAOS(){if(typeof AOS!=="undefined"){AOS.init({duration:600,easing:"ease-in-out",once:true,mirror:false})}}
if(document.readyState==="complete"){"requestIdleCallback" in window?requestIdleCallback(initAOS,{timeout:2000}):setTimeout(initAOS,300)}
else{window.addEventListener("load",function(){"requestIdleCallback" in window?requestIdleCallback(initAOS,{timeout:2000}):setTimeout(initAOS,300)})}

/* === Swiper: init ASAP after load (before FCP window) - key TBT fix === */
function initAllSwiper(){if(typeof Swiper==="undefined")return;document.querySelectorAll(".init-swiper").forEach(function(el){var cfg=JSON.parse(el.querySelector(".swiper-config").innerHTML.trim());el.classList.contains("swiper-tab")?initSwiperWithCustomPagination(el,cfg):new Swiper(el,cfg)})}
if(document.readyState==="complete"){initAllSwiper()}
else{window.addEventListener("load",initAllSwiper)}

/* === Isotope: lazy via IntersectionObserver === */
function initIsotope(){document.querySelectorAll(".isotope-layout").forEach(function(el){if(typeof Isotope==="undefined")return;var inst,layout=el.getAttribute("data-layout")||"masonry",filter=el.getAttribute("data-default-filter")||"*",sort=el.getAttribute("data-sort")||"original-order",cont=el.querySelector(".isotope-container");if(!cont)return;function createInst(){if(!inst)inst=new Isotope(cont,{itemSelector:".isotope-item",layoutMode:layout,filter:filter,sortBy:sort})}if("IntersectionObserver" in window){var io=new IntersectionObserver(function(entries,o){entries.forEach(function(en){if(en.isIntersecting){createInst();o.disconnect()}})},{rootMargin:"200px"});io.observe(el)}else{createInst()}el.querySelectorAll(".isotope-filters li").forEach(function(li){li.addEventListener("click",function(){createInst();var act=el.querySelector(".isotope-filters .filter-active");act&&act.classList.remove("filter-active");this.classList.add("filter-active");inst&&inst.arrange({filter:this.getAttribute("data-filter")})},false)})})}
if(document.readyState==="complete"){setTimeout(initIsotope,0)}else{window.addEventListener("load",function(){setTimeout(initIsotope,0)})}

/* === GLightbox: only on first user interaction === */
var _gInit=false;
function initGLightbox(){if(_gInit)return;_gInit=true;if(typeof GLightbox!=="undefined"){GLightbox({selector:".glightbox"})}}
["scroll","click","touchstart"].forEach(function(ev){window.addEventListener(ev,initGLightbox,{once:true,passive:true})});
setTimeout(initGLightbox,4000);

/* === PureCounter: defer via requestIdleCallback (below fold) === */
function initPureCounter(){if(typeof PureCounter!=="undefined"){new PureCounter}}
if(document.readyState==="complete"){"requestIdleCallback" in window?requestIdleCallback(initPureCounter,{timeout:3000}):setTimeout(initPureCounter,1000)}
else{window.addEventListener("load",function(){"requestIdleCallback" in window?requestIdleCallback(initPureCounter,{timeout:3000}):setTimeout(initPureCounter,1000)})}

/* === Skills animation === */
document.querySelectorAll(".skills-animation").forEach(function(el){if(typeof Waypoint!=="undefined"){new Waypoint({element:el,offset:"80%",handler:function(){el.querySelectorAll(".progress .progress-bar").forEach(function(b){b.style.width=b.getAttribute("aria-valuenow")+"%"})}})}});

/* === FAQ toggle === */
document.querySelectorAll(".faq-item").forEach(function(el){var hdr=el.querySelector(".faq-header");if(hdr){hdr.addEventListener("click",function(){el.classList.toggle("faq-active")})}else{el.querySelectorAll("h3, .faq-toggle").forEach(function(t){t.addEventListener("click",function(){el.classList.toggle("faq-active")})})}});

/* === Hash scroll on load === */
window.addEventListener("load",function(){if(window.location.hash){var target=document.querySelector(window.location.hash);if(target){setTimeout(function(){var top=parseInt(getComputedStyle(target).scrollMarginTop)||0;window.scrollTo({top:target.offsetTop-top,behavior:"smooth"})},100)}}});

/* === Nav active highlight === */
var navLinks=document.querySelectorAll(".navmenu a");
function updateNavActive(){navLinks.forEach(function(a){if(!a.hash)return;var sec=document.querySelector(a.hash);if(!sec)return;var sy=window.scrollY+200;sy>=sec.offsetTop&&sy<=sec.offsetTop+sec.offsetHeight?(document.querySelectorAll(".navmenu a.active").forEach(function(x){x.classList.remove("active")}),a.classList.add("active")):a.classList.remove("active")})}
window.addEventListener("load",updateNavActive);
document.addEventListener("scroll",updateNavActive,{passive:true});

/* === Copyright year === */
var yr=document.getElementById("year");if(yr)yr.textContent=new Date().getFullYear();
}();